/**
 * Counts the organization's *live* projects; the `projects` quota reads this.
 * Archiving a project frees its slot at once and restoring it takes one
 * again — only an archived project's rows, numbers and address stick around.
 */
export async function countProjects(
  orgId: OrgId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(projects)
    .where(
      and(
        orgPredicate(projects.orgId, orgId),
        ...compact(livePredicate(projects.archivedAt, scope)),
      ),
    )
    .get();
